/** Central Zustand store — single source of truth for the editor. */

import { create } from "zustand";
import { api, ApiSessionExpired, apiSessionId, isApiSessionCurrent } from "../api/client";
import { DPI } from "../hooks/useSnap";
import type { SnapGuide } from "../hooks/useSnap";
import { pushUndoState } from "../hooks/useUndoRedo";
import type {
  AxesLabels,
  BBox,
  CallRecord,
  ColumnDef,
  ElementDataLink,
  ElementDetails,
  FileTreeItem,
  FilesResponse,
  HitmapResponse,
  PlacedFigure,
  PreviewResponse,
  StatBracket,
  StyleOverrides,
  TabData,
  ThemeInfo,
} from "../types/editor";
import { createFigureActions } from "./figureActions";
import { createPersistActions } from "./persistActions";
import { createSyncActions } from "./syncActions";
import { rememberLastProject } from "./lastProjectMemory";
import { newId } from "../utils/newId";
import { gettext } from "@scitex/sdk/ui/ts/_base/gettext.ts";

interface ZoomControls {
  zoomIn: () => void;
  zoomOut: () => void;
  zoomToFit: () => void;
  resetView: () => void;
}

/** The canvas viewport. Session-scoped state, not component state: switching
 *  editor tabs unmounts the canvas, and the user's view must survive that
 *  (operator acceptance 7694: "preserve the new viewport across tab changes
 *  during the session"). */
export interface CanvasView {
  zoom: number;
  panX: number;
  panY: number;
}

interface EditorState {
  // ── Canvas figures ──────────────────────────────────────
  placedFigures: PlacedFigure[];
  selectedFigureId: string | null;
  selectedFigureIds: string[];

  // ── Legacy ──────────────────────────────────────────────
  hitmapImage: string | null;
  colorMap: Record<string, unknown>;
  /** The recipe the loaded hitmap depicts. A raster is rendered for ONE recipe,
   *  so this is what makes it per-figure instead of global: an overlay only
   *  samples the raster whose recipe is its own figure's (hitmapMatchesFigure). */
  hitmapRecipe: string | null;
  loading: boolean;

  // ── Selection ───────────────────────────────────────────
  selectedElement: string | null;
  selectedBbox: BBox | null;
  /** Inspected details of the selected element (value, row/column,
   *  series) — null while loading or when nothing is selected. */
  elementDetails: ElementDetails | null;
  /** Picked matrix cell (row/col) on an image/mesh element; null means
   *  the whole element. Refetching details carries it as row/col. */
  elementCell: { row: number; col: number } | null;
  /** Known matrix shapes per element key (from details shape) — lets a
   *  click on an already-selected matrix resolve its cell immediately. */
  elementShapes: Record<string, { rows: number; cols: number }>;

  // ── Files ───────────────────────────────────────────────
  files: FileTreeItem[];
  currentFile: string | null;
  workingDir: string | null;
  projectId: string | null;
  projectName: string | null;

  // ── Data ────────────────────────────────────────────────
  datatableTabs: Record<string, TabData>;
  activeTabId: string | null;
  /** The last datatable load failure's user-facing message, null when the
   *  table loaded fine. The Data pane renders it with a retry affordance
   *  instead of leaving a silently empty table (error-fallback-ui). */
  datatableLoadError: string | null;
  /** The stored project table's revision (opaque string from the server, null
   *  when the shown table did not come from the project). The save queue sends
   *  it as base_revision so a write based on a superseded table is refused
   *  (409) instead of discarding newer edits. */
  datatableRevision: string | null;

  // ── Style ───────────────────────────────────────────────
  darkMode: boolean;
  currentTheme: string;
  themes: string[];
  overrides: StyleOverrides;

  // ── Panel positions (mm) ────────────────────────────────
  panelPositions: Record<
    string,
    { left: number; top: number; width: number; height: number }
  >;
  figSizeMm: { width: number; height: number } | null;

  // ── Sync: Element ↔ Data ────────────────────────────────
  elementDataMap: Record<string, ElementDataLink>;
  highlightedDataRows: number[];

  // ── Sync: Calls & Labels (moved from Properties local state) ──
  calls: Record<string, CallRecord[]>;
  labels: Record<string, AxesLabels>;

  // ── Sync: Stat brackets ───────────────────────────────
  statBrackets: Record<string, StatBracket[]>;

  // ── Clipboard ──────────────────────────────────────────
  clipboard: PlacedFigure | null;

  // ── Snap ───────────────────────────────────────────────
  snapEnabled: boolean;
  activeSnapGuides: SnapGuide[];

  // ── Zoom / Debug / Rulers / Toast ──────────────────────
  zoomControls: ZoomControls | null;
  /** Last canvas viewport (zoom/pan) — kept here so a tab change, which
   *  unmounts the canvas, restores the view the user was working in. */
  canvasView: CanvasView | null;
  setCanvasView: (view: CanvasView) => void;
  /** Which figure set the view was last AUTO-FITTED for. Session-scoped on
   *  purpose: the canvas unmounts on every tab switch, so a component ref cannot
   *  remember "already fitted" — it reset and the remount refit threw the
   *  restored viewport away (measured live; acceptance 7694). */
  canvasFitKey: string | null;
  setCanvasFitKey: (key: string) => void;
  showHitmap: boolean;
  showRulers: boolean;
  rulerUnit: "mm" | "inch";
  toast: { message: string; type: "info" | "success" | "error" } | null;

  // ── Actions ─────────────────────────────────────────────
  loadPreview: () => Promise<void>;
  loadHitmap: () => Promise<void>;
  loadFiles: () => Promise<void>;
  loadThemes: () => Promise<void>;
  /** @param options.isCurrent — apply the server's table only when this still
   *  returns true after the read (the Data pane uses it to ignore a response a
   *  newer edit has overtaken). */
  loadDatatable: (options?: { isCurrent?: () => boolean }) => Promise<void>;
  loadPanelPositions: () => Promise<void>;

  addFigure: (path: string) => Promise<void>;
  removeFigure: (id: string) => void;
  selectFigure: (id: string | null) => void;
  moveFigure: (id: string, x: number, y: number) => void;
  alignFigures: (
    mode:
      | "left"
      | "right"
      | "top"
      | "bottom"
      | "center-h"
      | "center-v"
      | "axes-left"
      | "axes-right"
      | "axes-top"
      | "axes-bottom",
  ) => void;
  distributeFigures: (direction: "horizontal" | "vertical") => void;
  reorderPanelLetters: () => void;
  groupFigures: (ids: string[]) => void;
  ungroupFigures: (groupId: string) => void;

  toggleFigureSelection: (id: string) => void;

  copyFigure: () => void;
  pasteFigure: () => void;
  bringToFront: (id: string) => void;
  sendToBack: (id: string) => void;

  selectElement: (id: string | null, bbox?: BBox, figureId?: string) => void;
  setElementCell: (row: number, col: number) => void;
  switchFile: (path: string) => Promise<void>;
  switchTheme: (theme: string) => Promise<void>;
  updateOverrides: (overrides: StyleOverrides) => Promise<void>;
  save: () => Promise<void>;
  restore: () => Promise<void>;

  // ── Sync actions ───────────────────────────────────────
  loadCalls: (axIndex: number) => Promise<void>;
  loadLabels: (axIndex: number) => Promise<void>;
  loadElementDetails: () => Promise<void>;
  highlightDataForElement: (elementId: string | null) => void;
  refreshAfterMutation: () => Promise<void>;

  // ── Stats bracket actions ─────────────────────────────
  loadStatBrackets: (axIndex?: number) => Promise<void>;
  addStatBracket: (
    bracket: Omit<StatBracket, "bracket_id"> & { bracket_id?: string },
  ) => Promise<string | null>;
  removeStatBracket: (axIndex: number, bracketId: string) => Promise<boolean>;
  moveLegend: (axIndex: number, x: number, y: number) => Promise<boolean>;

  setDarkMode: (dark: boolean) => void;
  toggleHitmap: () => void;
  toggleSnap: () => void;
  toggleRulers: () => void;
  toggleRulerUnit: () => void;
  showToast: (msg: string, type?: "info" | "success" | "error") => void;
  clearToast: () => void;

  /** Plot family picked in the rail; the Data pane plots with it. */
  plotFamily: string | null;
  setPlotFamily: (family: string | null) => void;
}

/* eslint-disable @typescript-eslint/no-explicit-any */
export const useEditorStore = create<EditorState>((set, get) => ({
  // ── Initial state ───────────────────────────────────────
  placedFigures: [],
  selectedFigureId: null,
  selectedFigureIds: [],
  hitmapImage: null,
  colorMap: {},
  hitmapRecipe: null,
  loading: false,
  selectedElement: null,
  selectedBbox: null,
  elementDetails: null,
  elementCell: null,
  elementShapes: {},
  files: [],
  currentFile: null,
  workingDir: null,
  projectId: null,
  projectName: null,
  datatableTabs: {},
  activeTabId: null,
  datatableLoadError: null,
  datatableRevision: null,
  elementDataMap: {},
  highlightedDataRows: [],
  calls: {},
  labels: {},
  statBrackets: {},
  panelPositions: {},
  figSizeMm: null,
  darkMode: false,
  currentTheme: "SCITEX",
  themes: [],
  overrides: {},
  clipboard: null,
  snapEnabled: true,
  activeSnapGuides: [],
  zoomControls: null,
  canvasView: null,
  canvasFitKey: null,
  showHitmap: false,
  showRulers: true,
  rulerUnit:
    (localStorage.getItem("figrecipe-ruler-unit") as "mm" | "inch") || "mm",
  toast: null,

  // ── Figure actions (from slice) ─────────────────────────
  ...createFigureActions(set as any, get as any),

  // ── Persist actions (save/restore/theme/overrides) ──────
  ...createPersistActions(set as any, get as any),

  // ── Multi-selection ────────────────────────────────────
  toggleFigureSelection: (id: string) => {
    set((s) => {
      const current = s.selectedFigureIds;
      // If nothing selected yet, start multi-select from current + new
      let base =
        current.length > 0
          ? current
          : s.selectedFigureId
            ? [s.selectedFigureId]
            : [];
      const ids = base.includes(id)
        ? base.filter((fid) => fid !== id)
        : [...base, id];
      return {
        selectedFigureIds: ids,
        selectedFigureId: ids.length > 0 ? ids[ids.length - 1] : null,
        selectedElement: null,
        selectedBbox: null,
      };
    });
  },

  // ── Clipboard & layer operations ──────────────────────
  copyFigure: () => {
    const { selectedFigureId, placedFigures } = get();
    const fig = placedFigures.find((f) => f.id === selectedFigureId);
    if (fig) set({ clipboard: { ...fig } });
  },

  pasteFigure: () => {
    const { clipboard, placedFigures } = get();
    if (!clipboard) return;
    const newFig: PlacedFigure = {
      ...clipboard,
      id: newId(),
      x: clipboard.x + 20,
      y: clipboard.y + 20,
      groupId: undefined,
    };
    set({
      placedFigures: [...placedFigures, newFig],
      selectedFigureId: newFig.id,
    });
    pushUndoState();
  },

  bringToFront: (id: string) => {
    set((s) => {
      const idx = s.placedFigures.findIndex((f) => f.id === id);
      if (idx < 0 || idx === s.placedFigures.length - 1) return {};
      const figs = [...s.placedFigures];
      const [fig] = figs.splice(idx, 1);
      figs.push(fig);
      return { placedFigures: figs };
    });
    pushUndoState();
  },

  sendToBack: (id: string) => {
    set((s) => {
      const idx = s.placedFigures.findIndex((f) => f.id === id);
      if (idx <= 0) return {};
      const figs = [...s.placedFigures];
      const [fig] = figs.splice(idx, 1);
      figs.unshift(fig);
      return { placedFigures: figs };
    });
    pushUndoState();
  },

  // ── Load actions ────────────────────────────────────────
  loadPreview: async () => {
    const session = apiSessionId();
    set({ loading: true });
    try {
      const dark = get().darkMode;
      const data = await api.get<PreviewResponse>(
        `preview?dark_mode=${dark}&dpi=${DPI}`,
      );
      if (data.dark_mode !== undefined) set({ darkMode: data.dark_mode });
      const { placedFigures, selectedFigureId, currentFile } = get();
      if (placedFigures.length === 0) {
        const recipeParam =
          new URLSearchParams(window.location.search).get("recipe") || "";
        const recipePath =
          currentFile ?? recipeParam.split("/").pop() ?? "preview";
        const fig: PlacedFigure = {
          id: newId(),
          path: recipePath,
          x: 0,
          y: 0,
          previewImage: data.image,
          bboxes: data.bboxes,
          imgSize: data.img_size,
          panelLetter: "A",
        };
        set({ placedFigures: [fig], selectedFigureId: fig.id });
      } else if (selectedFigureId) {
        set((s) => ({
          placedFigures: s.placedFigures.map((f) =>
            f.id === selectedFigureId
              ? {
                  ...f,
                  previewImage: data.image,
                  bboxes: data.bboxes,
                  imgSize: data.img_size,
                }
              : f,
          ),
        }));
      }
    } catch (e) {
      if (e instanceof ApiSessionExpired) return;
      console.error("[Editor] Failed to load preview:", e);
      get().showToast(gettext("Failed to load preview"), "error");
    } finally {
      if (isApiSessionCurrent(session)) set({ loading: false });
    }
  },

  loadHitmap: async () => {
    // The raster the server renders depicts the recipe IT has open, and the
    // frontend mirrors that as currentFile — falling back to the selected
    // figure's own recipe while the files list is still resolving. Captured
    // BEFORE the request: a response that lands after the user opened something
    // else must not re-label itself as that figure's picture.
    const forRecipe =
      get().currentFile ??
      get().placedFigures.find((f) => f.id === get().selectedFigureId)?.path ??
      null;
    try {
      const data = await api.get<HitmapResponse>("hitmap");
      set({ hitmapImage: data.image, colorMap: data.color_map, hitmapRecipe: forRecipe });
    } catch (e) {
      console.error("[Editor] Failed to load hitmap:", e);
    }
  },

  loadFiles: async () => {
    try {
      const data = await api.get<FilesResponse>("api/files");
      const workingDir = data.working_dir ?? null;
      // TODO 142/149: remember the project FigRecipe just opened as an
      // app-local preference, kept separate from the hub's global
      // "Current Project" state (namespaced localStorage key).
      rememberLastProject(workingDir);
      set({
        files: data.tree,
        currentFile: data.current_file,
        workingDir,
      });
    } catch (e) {
      console.error("[Editor] Failed to load files:", e);
    }
  },

  loadThemes: async () => {
    try {
      const data = await api.get<ThemeInfo>("list_themes");
      set({ themes: data.themes, currentTheme: data.current });
    } catch (e) {
      console.error("[Editor] Failed to load themes:", e);
    }
  },

  loadDatatable: async (options?) => {
    set({ datatableLoadError: null });
    try {
      const data = await api.get<{
        columns: ColumnDef[];
        rows: (string | number)[][];
        source?: string | null;
        revision?: string | null;
        element_data_map?: Record<
          string,
          { columns: string[]; row_indices: number[] }
        >;
      }>("datatable/data");
      // A read that began before a newer edit must not put the older table back
      // on screen: the Data pane's save queue says whether this response is
      // still current, and the newest edit answers for the table anyway.
      const { isCurrent } = options ?? {};
      if (isCurrent && !isCurrent()) return;
      const tab: TabData = {
        id: "main",
        label: gettext("Data"),
        columns: data.columns ?? [],
        rows: data.rows ?? [],
        source:
          data.source === "project" ||
          data.source === "import" ||
          data.source === "record"
            ? data.source
            : null,
      };
      // Build element-data mapping if provided by backend
      const elementDataMap: Record<
        string,
        { columns: string[]; rowIndices: number[] }
      > = {};
      if (data.element_data_map) {
        for (const [key, val] of Object.entries(data.element_data_map)) {
          elementDataMap[key] = {
            columns: val.columns,
            rowIndices: val.row_indices,
          };
        }
      }
      set({
        datatableTabs: { main: tab },
        activeTabId: "main",
        elementDataMap,
        datatableRevision:
          typeof data.revision === "string" ? data.revision : null,
      });
    } catch (e) {
      console.warn("[Editor] No datatable data available:", e);
      // Fail loud, not blank: the Data pane renders this with a retry
      // affordance. The technical detail stays in the console above; the
      // user sees a translated explanation.
      set({ datatableLoadError: gettext("Could not load the data table") });
    }
  },

  loadPanelPositions: async () => {
    try {
      const data = await api.get<Record<string, any>>("get_axes_positions");
      const figsize = data._figsize as
        | { width_mm: number; height_mm: number }
        | undefined;
      const positions: Record<
        string,
        { left: number; top: number; width: number; height: number }
      > = {};
      for (const [key, val] of Object.entries(data)) {
        if (key !== "_figsize" && val && "left" in val) positions[key] = val;
      }
      set({
        panelPositions: positions,
        figSizeMm: figsize
          ? { width: figsize.width_mm, height: figsize.height_mm }
          : null,
      });
    } catch (e) {
      console.warn("[Editor] No panel positions available:", e);
    }
  },

  // ── Sync actions (calls, labels, highlights, stats brackets) ──
  ...createSyncActions(set as any, get as any),

  // ── Selection ───────────────────────────────────────────
  selectElement: (elementId, bbox, figureId) => {
    set({
      selectedElement: elementId,
      selectedBbox: bbox ?? null,
      selectedFigureId: figureId ?? get().selectedFigureId,
      // A new element starts un-detailed at the whole element: the cell
      // belongs to the previous pick and must not leak into its details.
      elementCell: null,
      elementDetails: elementId ? get().elementDetails : null,
    });
    // Sync gap fix: load calls/labels and highlight data rows
    if (bbox?.ax_index !== undefined) {
      get().loadCalls(bbox.ax_index);
      get().loadLabels(bbox.ax_index);
    }
    get().highlightDataForElement(elementId);
    if (elementId) get().loadElementDetails();
  },

  setElementCell: (row, col) => {
    if (!get().selectedElement) return;
    set({ elementCell: { row, col } });
    get().loadElementDetails();
  },

  switchFile: async (path) => get().addFigure(path),

  // ── UI toggles ──────────────────────────────────────────
  setDarkMode: async (dark) => {
    set({ darkMode: dark });
    // Only update backend if figures are loaded (avoids "No recipe loaded" error)
    const { placedFigures } = get();
    if (placedFigures.length === 0) return;
    try {
      const data = await api.post<PreviewResponse>("update", {
        dark_mode: dark,
      });
      if (data?.image) {
        const { selectedFigureId } = get();
        if (selectedFigureId) {
          set((s) => ({
            placedFigures: s.placedFigures.map((f) =>
              f.id === selectedFigureId
                ? {
                    ...f,
                    previewImage: data.image,
                    bboxes: data.bboxes,
                    imgSize: data.img_size,
                  }
                : f,
            ),
          }));
        }
      }
    } catch (e) {
      console.error("[Editor] setDarkMode API failed:", e);
    }
  },
  toggleHitmap: () => set((s) => ({ showHitmap: !s.showHitmap })),
  setCanvasView: (view) => set({ canvasView: view }),
  setCanvasFitKey: (key) => set({ canvasFitKey: key }),
  toggleSnap: () => set((s) => ({ snapEnabled: !s.snapEnabled })),
  toggleRulers: () => set((s) => ({ showRulers: !s.showRulers })),
  toggleRulerUnit: () =>
    set((s) => {
      const next = s.rulerUnit === "mm" ? "inch" : "mm";
      localStorage.setItem("figrecipe-ruler-unit", next);
      return { rulerUnit: next };
    }),
  showToast: (message, type = "info") => {
    set({ toast: { message, type } });
    // Errors persist until dismissed (shown in the AlertBanner -- fail-loud);
    // info/success auto-clear as transient toasts.
    if (type !== "error") {
      setTimeout(() => set({ toast: null }), 3000);
    }
  },
  clearToast: () => set({ toast: null }),

  plotFamily: null,
  setPlotFamily: (family) => set({ plotFamily: family }),
}));

/** Project content and undo targets belong to one mounted workspace. */
export function resetEditorWorkspace(): void {
  const { darkMode, snapEnabled, showRulers, rulerUnit, showHitmap } = useEditorStore.getState();
  useEditorStore.setState({
    ...useEditorStore.getInitialState(),
    darkMode, snapEnabled, showRulers, rulerUnit, showHitmap,
  }, true);
}
